import copy

def step(grid: list[list[int]], action: int, x: int = -1, y: int = -1) -> list[list[int]]:
    """
    Simulates one step of the grid game.
    """
    new_grid = copy.deepcopy(grid)

    # Helper to find blocks
    def find_blocks(g):
        blocks = []
        # Look for 6x6 areas with 6-border
        for r in range(64 - 5):
            for c in range(64 - 5):
                # Check top border
                if all(g[r][c+i] == 6 for i in range(6)):
                    # Check bottom border
                    if all(g[r+5][c+i] == 6 for i in range(6)):
                        # Check left/right borders (corners already checked)
                        if g[r+1][c] == 6 and g[r+2][c] == 6 and g[r+3][c] == 6 and g[r+4][c] == 6:
                            if g[r+1][c+5] == 6 and g[r+2][c+5] == 6 and g[r+3][c+5] == 6 and g[r+4][c+5] == 6:
                                blocks.append((c, r))
        return blocks

    blocks = find_blocks(new_grid)
    if not blocks:
        return new_grid

    # Determine active block
    # Heuristic: The block that is "highest" (smallest y) is the player block?
    # Or the one that was clicked?
    # For now, assume the top-most block is the active one for movement.
    # And for slot operations, we need to know which slot.

    # Let's assume the active block is the one with the smallest y coordinate.
    active_block = min(blocks, key=lambda b: b[1])
    bx, by = active_block

    # Slot position relative to block
    # Slot is 2x6, located at (bx+6, by+2) to (bx+11, by+3)
    slot_x, slot_y = bx + 6, by + 2

    # Pattern to fill
    pattern = [
        [2, 1, 1, 2, 1, 1],
        [1, 1, 2, 1, 1, 2]
    ]

    if action == 3 or action == 7:
        # Clear slot: set to 4
        for dy in range(2):
            for dx in range(6):
                new_grid[slot_y + dy][slot_x + dx] = 4

    elif action == 4:
        # Fill slot: set to pattern
        for dy in range(2):
            for dx in range(6):
                new_grid[slot_y + dy][slot_x + dx] = pattern[dy][dx]

    elif action == 1:
        # Move block UP
        # Check if move is valid (no collision with other blocks or boundaries)
        # For simplicity, just move if possible
        new_by = by - 1
        if new_by >= 0:
            # Check collision with other blocks
            collision = False
            for other_bx, other_by in blocks:
                if other_bx == bx and abs(other_by - new_by) < 6:
                    collision = True
                    break
            if not collision:
                # Move the block
                # Copy old block content to new position
                # And clear old position?
                # The background is 5.
                for dy in range(6):
                    for dx in range(6):
                        new_grid[new_by + dy][bx + dx] = new_grid[by + dy][bx + dx]
                        new_grid[by + dy][bx + dx] = 5 # Clear old

                # Also move the slot?
                # The slot is part of the block's "area" but not inside the 6x6.
                # It seems the slot moves with the block.
                # Clear old slot
                for dy in range(2):
                    for dx in range(6):
                        new_grid[slot_y + dy][slot_x + dx] = 4
                # Set new slot
                new_slot_y = new_by + 2
                for dy in range(2):
                    for dx in range(6):
                        # Preserve pattern if it was filled?
                        # Or just move the 4s?
                        # Let's assume the slot content moves with the block.
                        # But we just cleared it above.
                        # We need to read from old slot before clearing.
                        pass 

                # Re-do move properly
                # Read old block and slot
                old_block = []
                for dy in range(6):
                    row = []
                    for dx in range(6):
                        row.append(new_grid[by + dy][bx + dx])
                    old_block.append(row)

                old_slot = []
                for dy in range(2):
                    row = []
                    for dx in range(6):
                        row.append(new_grid[slot_y + dy][slot_x + dx])
                    old_slot.append(row)

                # Clear old positions
                for dy in range(6):
                    for dx in range(6):
                        new_grid[by + dy][bx + dx] = 5
                for dy in range(2):
                    for dx in range(6):
                        new_grid[slot_y + dy][slot_x + dx] = 4

                # Write new positions
                for dy in range(6):
                    for dx in range(6):
                        new_grid[new_by + dy][bx + dx] = old_block[dy][dx]
                new_slot_y = new_by + 2
                for dy in range(2):
                    for dx in range(6):
                        new_grid[new_slot_y + dy][slot_x + dx] = old_slot[dy][dx]

    elif action == 2:
        # Move block DOWN
        new_by = by + 1
        if new_by + 5 < 64:
            collision = False
            for other_bx, other_by in blocks:
                if other_bx == bx and abs(other_by - new_by) < 6:
                    collision = True
                    break
            if not collision:
                # Similar move logic
                old_block = []
                for dy in range(6):
                    row = []
                    for dx in range(6):
                        row.append(new_grid[by + dy][bx + dx])
                    old_block.append(row)

                old_slot = []
                for dy in range(2):
                    row = []
                    for dx in range(6):
                        row.append(new_grid[slot_y + dy][slot_x + dx])
                    old_slot.append(row)

                for dy in range(6):
                    for dx in range(6):
                        new_grid[by + dy][bx + dx] = 5
                for dy in range(2):
                    for dx in range(6):
                        new_grid[slot_y + dy][slot_x + dx] = 4

                for dy in range(6):
                    for dx in range(6):
                        new_grid[new_by + dy][bx + dx] = old_block[dy][dx]
                new_slot_y = new_by + 2
                for dy in range(2):
                    for dx in range(6):
                        new_grid[new_slot_y + dy][slot_x + dx] = old_slot[dy][dx]

